body { font-family: "Times New Roman", Times, serif; font-size: 10pt; color: #000; background: #fff; margin: 0; padding: 0; }

/* ── KOP persis seperti Surat Jawaban ── */
.kop {
    width: 100%;
    border-collapse: collapse;
    border-bottom: 5px solid #1a4fa0;
