.kop-teks { padding-left: 14px; text-align: center; vertical-align: bottom; }
.kop-pt {
    font-size: 24pt;
    font-weight: bold;
    color: #1a4fa0;
    font-family: "Times New Roman", Times, serif;
    letter-spacing: 1px;
    line-height: 1.8;
