    text-align: center;
}
.kop-alamat {
    font-size: 14pt;
    font-weight: bold;
    color: #1a4fa0;
    font-family: "Times New Roman", Times, serif;
    line-height: 1;
    text-align: center;
}
.garis-bawah {
    height: 2px;
    background: #1a4fa0;
    margin-bottom: 0;
}
.tagline {
    background: #fff;
    color: #1a4fa0;
    text-align: center;
    font-size: 14pt;
    font-weight: bold;
    font-family: "Times New Roman", Times, serif;
    letter-spacing: 1.5px;
    padding: 6px 0;
    margin-bottom: 16px;
    border-top: 2px solid #1a4fa0;
    border-bottom: 2px solid #1a4fa0;
}

/* ── JUDUL ── */
.judul {
    text-align: center;
    margin-bottom: 14px;
}
.judul-utama {
    font-size: 14pt;
    font-weight: bold;
    font-family: "Times New Roman", Times, serif;
    text-transform: uppercase;
    letter-spacing: 1px;
}
.judul-periode {
    font-size: 10.5pt;
    font-family: "Times New Roman", Times, serif;
    font-weight: bold;
    margin-top: 3px;
}

/* ── TABEL ── */
table.ranking {
    width: 100%;
    margin-left: 0;
    margin-right: 0;
    border-collapse: collapse;
    font-size: 9pt;
    font-family: "Times New Roman", Times, serif;
    margin-bottom: 12px;
}
table.ranking thead tr { background: #1a4fa0; color: #fff; }
table.ranking thead th {
    padding: 5px 4px;
    text-align: center;
    font-size: 8.5pt;
    border: 1px solid #1a4fa0;
    line-height: 1.3;
    font-family: "Times New Roman", Times, serif;
}
table.ranking tbody td {
    padding: 4px 5px;
    border: 1px solid #bbb;
    text-align: center;
    vertical-align: middle;
}
table.ranking tbody td.left { text-align: left; }
table.ranking tbody tr.ganjil { background: #dbeafe; }
table.ranking tbody tr.genap  { background: #ffffff; }

.rank-num { font-weight: bold; }
.nilai-akhir { font-weight: bold; font-size: 10pt; }
.terbaik-badge {
    font-size: 7pt;
    color: #7a5c00;
    background: #fef08a;
    border: 0.5px solid #c9a227;
    border-radius: 3px;
    padding: 1px 4px;
    margin-left: 4px;
}

/* ── KETERANGAN ── */
.keterangan { display:none; }

/* ── TTD ── */
.ttd { display: flex; justify-content: flex-start; }
.ttd-box { text-align: left; font-size: 10.5pt; font-family: "Times New Roman", Times, serif; }
.ttd-kota { margin-bottom: 60px; }
.ttd-nama { font-weight: normal; text-decoration: underline; }
.ttd-jabatan { font-size: 9.5pt; margin-top: 2px; }

/* ── FOOTER ── */
.footer { display:none; }
</style>
</head>
